const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),{createRequire}=require('node:module');
const root=path.resolve(__dirname,'../../..'),r=createRequire(root+'/apps/api/package.json'),ts=r('typescript'),modules=new Map();
function load(relative){const file=path.resolve(root,relative);if(modules.has(file))return modules.get(file).exports;const module={exports:{}};modules.set(file,module);
 function req(name){if(name==='@nestjs/common')return r(name);if(name==='src/core/database/prisma.service'||name.includes('/core/database/'))return{PrismaService:class{}};
  if(name.endsWith('contest.service')||name.endsWith('submission.service'))return{};
  if(name.startsWith('.'))return load(path.relative(root,path.resolve(path.dirname(file),name)+'.ts'));return r(name)}
 const code=ts.transpileModule(fs.readFileSync(file,'utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022,experimentalDecorators:true,esModuleInterop:true}}).outputText;new Function('require','module','exports',code)(req,module,module.exports);return module.exports;
}
async function main(){const checks=[],{ContestPageService}=load('apps/api/src/modules/submission/contest-page.service.ts');let gates=0,contests=0,problems=0,personal=0;
 const gate={id:2,contestVersion:'10',problemVersion:'20',problemId:67,show:false,timeStart:new Date(0),timeEnd:new Date(Date.now()+60000),scoreboardPolicy:'AFTER_CONTEST'};
 let problemName='original',absent=false;const database={$queryRaw:async()=>{gates++;return absent?[]:[{...gate}]},problem:{findFirst:async()=>({id:67}),findUnique:async()=>{problems++;return{id:67,name:problemName,show:false}}}};
 const service=new ContestPageService(database,{findOneById:async()=>{contests++;return{id:2,name:'contest',timeStart:new Date(0),timeEnd:gate.timeEnd,scoreboardPolicy:'AFTER_CONTEST'}}},{findFirstByProblemIdAndUserId:async(_id,userId)=>{personal++;return{id:userId,userId,sourceCode:'private-'+userId}}});
 const pages=await Promise.all(Array.from({length:100},(_,i)=>service.problemPage(2,67,{id:i+1,role:'user'})));assert.equal(gates,100);assert.equal(contests,1);assert.equal(problems,1);assert.equal(personal,100);pages.forEach((x,i)=>{assert.equal(x.status,200);assert.equal(x.body.latestSubmission.userId,i+1);assert.equal(x.body.latestSubmission.sourceCode,'private-'+(i+1));assert(x.body.serverTime instanceof Date)});checks.push('100 concurrent pages share one contest and one problem metadata load; gates and each user’s latest submission remain fresh');
 problemName='changed';gate.problemVersion='21';assert.equal((await service.problemPage(2,67,{id:1,role:'user'})).body.problem.name,'changed');assert.equal(problems,2);
 gate.timeStart=new Date(Date.now()+60000);assert.equal((await service.problemPage(2,67,{id:1,role:'user'})).status,403);assert.equal(personal,101);gate.timeStart=new Date(0);gate.problemId=null;assert.equal((await service.problemPage(2,67,{id:1,role:'user'})).status,404);absent=true;assert.equal((await service.problemPage(2,67,{id:1,role:'user'})).status,404);checks.push('row-version changes invalidate immediately; a warm cache never bypasses changed schedule, membership or missing-contest checks');
 const {pageMetadata}=load('apps/api/src/utils/page-metadata-cache.ts'),db={};let reads=0;await pageMetadata(db,'old',async()=>++reads);for(let i=0;i<128;i++)await pageMetadata(db,'other-'+i,async()=>0);assert.equal(await pageMetadata(db,'old',async()=>++reads),2);await assert.rejects(pageMetadata(db,'failure',async()=>{throw Error('fixture')}));assert.equal(await pageMetadata(db,'failure',async()=>3),3);checks.push('metadata cache is bounded and failed loads are not retained');
 console.log(JSON.stringify({passed:true,checks,productionWrites:0}));}
main().catch(error=>{console.error(error);process.exitCode=1});
